const COVERAGE_BODY: Json = {target: {target: 'relation-expansion'}, scope: {scope: 'fs-subtree', path: []}, mode: 'complete-within-scope',
  provider: {$id: 'hx.fs/builtin'}, cause: {cause: 'other', detail: 'No_change_exclusion'}};
