  const transport: TransportTelemetry = {startedAt: '2026-10-15T08:39:59.000Z', durationMs: 200, startupLatencyMs: 10, processDurationMs: 200,
    stdoutBytes: 300, stderrBytes: 0, stderrBytesRetained: 0, frames: decoded.length};
