const provided = (document: Json): Promise<JsonValue> => providedResult(resultFromJson(document));
interface Base {
  readonly name: string;
  readonly kind: string;
  readonly licensed: boolean;
  readonly shape: Shape;
  /** The provider output, deeply frozen: every cell shares its untouched nodes. */
  readonly reading: JsonValue;
}
/** Every kind given under both licences in each shape, through the real registration (104 for all 13 kinds). */
async function baseReadings(kinds: readonly string[]): Promise<Base[]> {
  const bases: Base[] = [];
  for (const kind of kinds) {
    for (const licensed of LICENCES) {
      for (const shape of SHAPES) {
        bases.push({name: `${kind} ${licensed ? 'licensed' : 'unlicensed'} ${shape}`, kind, licensed, shape,
          reading: deepFrozen(await provided(baseDocument(kind, licensed, shape)))});
      }
    }
  }
  return bases;
}
/** The content rows a base reading's shape pins, the misreads listed by name. */
